<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowRight, ArrowUpRight, Plus, FileText, Upload, Search, X, Send, Square, Check, Database, MessageSquare, Library, RefreshCw, ChevronRight, BookOpen, ShieldCheck, Clock3, Workflow } from 'lucide-vue-next'
import { api, authorizedFetch, list } from '../api'
import { readSSE } from '../api/sse'
import { useAuth } from '../stores/auth'
const route = useRoute(), router = useRouter(), auth = useAuth()
const section = computed(() => String(route.params.section))
const titles: Record<string, string[]> = { overview: ['知识，从这里连接', '汇聚团队经验，让每一次提问都有可靠的答案。'], knowledge: ['知识空间', '整理团队资料，让有价值的知识随时可用。'], chat: ['知识问答', '从当前可访问的资料中寻找答案，并追溯每一处来源。'], retrieval: ['检索调试', '查看授权范围内的召回片段，理解答案从何而来。'], tools: ['只读工具', '执行受权限约束的检索、原文摘要与业务统计。'], evaluation: ['效果评估', '在固定开发集上比较召回结果，保留真实的实验记录。'], monitoring: ['调用记录', '查看处理与生成状态，通过追踪编号定位问题。'] }
const kbs = ref<any[]>([]), docs = ref<any[]>([]), dashboard = ref<any>({}), selectedKb = ref(''), filter = ref('')
const error = ref(''), notice = ref(''), busy = ref(false), showCreate = ref(false), kbName = ref(''), kbDescription = ref(''), visibility = ref('private')
const fileInput = ref<HTMLInputElement>(), versionTarget = ref(''), source = ref<any>(null)
const conversations = ref<any[]>([]), activeConversation = ref(''), messages = ref<any[]>([]), question = ref(''), streaming = ref(false), runId = ref('')
const searchQuery = ref(''), hits = ref<any[]>([]), toolName = ref('DataAnalysisTool'), toolArgs = ref('{\n  "date_from": "2026-01-01",\n  "date_to": "2026-12-31",\n  "group_by": "category"\n}'), toolResult = ref<any>(null)
const datasets = ref<any[]>([]), evalRuns = ref<any[]>([]), calls = ref<any[]>([]), evalMode = ref('hybrid')
let controller: AbortController | null = null
const visibleDocs = computed(() => docs.value.filter(d => d.title.toLowerCase().includes(filter.value.toLowerCase())))
const readableError = (e: any) => { error.value = e.message || '操作失败，请稍后重试' }
async function protect(fn: () => Promise<void>) { error.value = ''; busy.value = true; try { await fn() } catch (e) { readableError(e) } finally { busy.value = false } }
async function load() {
  try {
    const [bases, stats] = await Promise.all([api('/knowledge-bases'), api('/monitoring/dashboard')])
    kbs.value = list(bases); dashboard.value = stats
    if (!selectedKb.value && kbs.value.length) selectedKb.value = kbs.value[0].id
    await loadDocs()
    if (section.value === 'chat') conversations.value = list(await api('/conversations'))
    if (section.value === 'evaluation') { datasets.value = await api('/evaluations/datasets'); evalRuns.value = await api('/evaluations/runs') }
    if (section.value === 'monitoring') calls.value = await api('/monitoring/calls')
  } catch (e) { readableError(e) }
}
async function loadDocs() { docs.value = selectedKb.value ? list(await api(`/knowledge-bases/${selectedKb.value}/documents`)) : [] }
watch(section, () => { error.value = ''; notice.value = ''; load() })
watch(selectedKb, () => protect(loadDocs))
onMounted(load)
const polling = setInterval(() => { if (docs.value.some(d => !['READY', 'FAILED', 'CANCELLED'].includes(d.status))) loadDocs().catch(readableError); if (section.value === 'evaluation' && evalRuns.value.some(r => ['PENDING', 'RUNNING'].includes(r.status))) api('/evaluations/runs').then(r => { evalRuns.value = r }).catch(readableError) }, 2500)
onUnmounted(() => { clearInterval(polling); controller?.abort() })
async function createKb() { await protect(async () => { const kb = await api('/knowledge-bases', { method: 'POST', body: JSON.stringify({ name: kbName.value, description: kbDescription.value, visibility: visibility.value }) }); selectedKb.value = kb.id; showCreate.value = false; kbName.value = ''; kbDescription.value = ''; await load() }) }
async function uploadFile(event: Event) { const input = event.target as HTMLInputElement; const file = input.files?.[0]; if (!file || !selectedKb.value) return; await protect(async () => { const form = new FormData(); form.append('file', file); if (versionTarget.value) form.append('document_id', versionTarget.value); const result = await api(`/knowledge-bases/${selectedKb.value}/documents`, { method: 'POST', body: form }); notice.value = `文档已提交处理，任务编号 ${result.task_id.slice(0, 8)}`; await loadDocs() }); input.value = ''; versionTarget.value = '' }
async function download(doc: any) { await protect(async () => { const r = await authorizedFetch(`/documents/${doc.id}/download`); if (!r.ok) throw new Error('无权下载或文件暂不可用'); const url = URL.createObjectURL(await r.blob()); const a = document.createElement('a'); a.href = url; a.download = doc.title; a.click(); URL.revokeObjectURL(url) }) }
async function deleteDocument(doc: any) { if (!confirm(`删除“${doc.title}”？此文档将立即退出检索范围。`)) return; await protect(async () => { await api(`/documents/${doc.id}`, { method: 'DELETE' }); await loadDocs() }) }
async function newConversation() { const c = await api('/conversations', { method: 'POST', body: JSON.stringify({ kb_ids: selectedKb.value ? [selectedKb.value] : [] }) }); activeConversation.value = c.id; messages.value = []; conversations.value.unshift(c) }
async function openConversation(id: string) { if (streaming.value) return; await protect(async () => { activeConversation.value = id; messages.value = await api(`/conversations/${id}/messages`) }) }
async function send() {
  if (!question.value.trim() || streaming.value) return
  error.value = ''; const text = question.value.trim(); question.value = ''; streaming.value = true; runId.value = ''; controller = new AbortController()
  try {
    if (!activeConversation.value) await newConversation()
    messages.value.push({ role: 'user', content: text, status: 'completed' })
    const outgoing: any = { role: 'assistant', content: '', references: [], status: 'streaming' }; messages.value.push(outgoing)
    const current = messages.value[messages.value.length - 1]
    const response = await authorizedFetch(`/conversations/${activeConversation.value}/messages:stream`, { method: 'POST', signal: controller.signal, headers: { 'Idempotency-Key': crypto.randomUUID() }, body: JSON.stringify({ question: text }) })
    await readSSE(response, ({ event, data }) => { if (event === 'meta') { runId.value = data.run_id; current.id = data.message_id } if (event === 'delta') current.content += data.text; if (event === 'references') current.references = data.sources; if (event === 'done') current.status = data.status; if (event === 'error') error.value = `回答生成失败（${data.code}），追踪编号 ${data.trace_id}` })
  } catch (e: any) { if (e.name !== 'AbortError') readableError(e) }
  finally { streaming.value = false; if (activeConversation.value) { try { messages.value = await api(`/conversations/${activeConversation.value}/messages`); conversations.value = list(await api('/conversations')) } catch (e) { readableError(e) } } }
}
async function stop() { if (runId.value) await api(`/runs/${runId.value}/cancel`, { method: 'POST' }).catch(readableError); controller?.abort() }
async function openSource(ref: any) { await protect(async () => { source.value = await api(`/references/${ref.id}`) }) }
async function retrieve() { await protect(async () => { const r = await api('/retrieval/search', { method: 'POST', body: JSON.stringify({ query: searchQuery.value, kb_ids: selectedKb.value ? [selectedKb.value] : [] }) }); hits.value = r.sources }) }
async function executeTool() { await protect(async () => { toolResult.value = await api('/agents/tools', { method: 'POST', body: JSON.stringify({ tool: toolName.value, args: JSON.parse(toolArgs.value) }) }) }) }
watch(toolName, name => { toolArgs.value = JSON.stringify(name === 'KnowledgeSearchTool' ? { query: '退款政策', top_k: 5 } : name === 'DocumentSummaryTool' ? { document_id: docs.value[0]?.id || '', focus: '' } : { date_from: '2026-01-01', date_to: '2026-12-31', group_by: 'category' }, null, 2); toolResult.value = null })
async function evaluate() { await protect(async () => { await api('/evaluations/runs', { method: 'POST', body: JSON.stringify({ dataset_id: datasets.value[0].id, mode: evalMode.value }) }); evalRuns.value = await api('/evaluations/runs') }) }
const statuses: Record<string, string> = { READY: '已就绪', FAILED: '处理失败', CANCELLED: '已取消', PENDING: '待处理', PARSING: '解析中', EMBEDDING: '向量化中', CHUNKING: '切片中', INDEXING: '索引中', RETRY_WAIT: '等待重试' }
const statusLabel = (status: string) => statuses[status] || status
const date = (v: string) => new Date(v).toLocaleDateString('zh-CN', { month: '2-digit', day: '2-digit' })
</script>

<template>
  <div class="page">
    <div class="page-title"><div><div class="eyebrow">{{ section === 'overview' ? 'YOUR KNOWLEDGE, CONNECTED' : 'KNOWFLOW WORKSPACE' }}</div><h1>{{ titles[section]?.[0] }}</h1><p>{{ titles[section]?.[1] }}</p></div><button v-if="section === 'overview' || section === 'knowledge'" class="primary" @click="showCreate = true"><Plus :size="16"/>新建知识库</button><button v-else class="secondary" @click="load"><RefreshCw :size="15"/>刷新</button></div>
    <div v-if="error" class="error" role="alert">{{ error }}<button @click="error = ''" aria-label="关闭提示"><X :size="15"/></button></div><div v-if="notice" class="notice"><Check :size="16"/>{{ notice }}</div>
    <template v-if="section === 'overview'">
      <section class="hero"><div class="hero-copy"><span class="hero-kicker"><span class="status-dot"></span> KNOWLEDGE THAT WORKS FOR YOU</span><h2>好的答案，<br/>始于团队的共同知识。</h2><p>把散落的文档变成触手可及的经验。<br/>提一个问题，发现知识之间的连接。</p><button class="hero-button" @click="router.push('/chat')">开始一次知识对话<ArrowRight :size="17"/></button></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="knowledge-card card-a"><FileText :size="23"/><span>产品与服务<small>团队的实践与经验</small></span><Check :size="13"/></div><div class="knowledge-card card-b"><ShieldCheck :size="22"/><span>规范与制度<small>每一条规则都有来源</small></span></div><div class="art-center"><BookOpen :size="35"/></div><div class="knowledge-card card-c"><MessageSquare :size="23"/><span>连接知识与答案</span><ArrowUpRight :size="16"/></div><span class="art-dot dot-a"></span><span class="art-dot dot-b"></span><span class="art-cross">+</span></div></section>
      <div class="metrics"><div v-for="stat in [{ label: '可访问知识库', value: dashboard.knowledge_bases, icon: Library, suffix: '个空间' }, { label: '团队知识文档', value: dashboard.documents, icon: FileText, suffix: '份资料' }, { label: '我的知识对话', value: dashboard.my_runs, icon: MessageSquare, suffix: '次探索' }]" :key="stat.label" class="metric"><div><span>{{ stat.label }}</span><strong>{{ stat.value ?? '—' }}<small>{{ stat.suffix }}</small></strong></div><component :is="stat.icon" :size="20"/></div></div>
      <div class="section-heading"><h2>你的知识空间 <span>{{ kbs.length.toString().padStart(2, '0') }}</span></h2><RouterLink to="/knowledge">查看全部<ArrowRight :size="14"/></RouterLink></div>
      <div class="kb-grid"><button v-for="(kb, i) in kbs.slice(0, 3)" :key="kb.id" class="kb-card" @click="selectedKb = kb.id; router.push('/knowledge')"><div class="kb-card-top"><span class="kb-icon" :class="'color-' + i % 3"><Library :size="21"/></span><ArrowUpRight :size="18"/></div><h3>{{ kb.name }}</h3><p>{{ kb.description || '团队资料的可靠归处' }}</p><div class="kb-card-footer"><span><span class="status-dot"></span>{{ kb.visibility === 'tenant' ? '团队可见' : '私有空间' }}</span><span>{{ date(kb.created_at) }} 创建</span></div></button><button v-if="kbs.length < 3" class="kb-card create-card" @click="showCreate = true"><Plus :size="24"/><strong>创建新的知识空间</strong><span>让下一份知识在这里生长</span></button></div>
      <div class="section-heading"><h2>最近的知识文档</h2><RouterLink to="/knowledge">管理文档<ArrowRight :size="14"/></RouterLink></div>
      <div class="panel"><div v-for="doc in docs.slice(0, 4)" :key="doc.id" class="recent-doc"><span class="file-icon"><FileText :size="19"/></span><div><strong>{{ doc.title }}</strong><small>{{ kbs.find(k => k.id === selectedKb)?.name }} · {{ doc.active_version ? '版本 ' + doc.active_version : '尚未发布' }}</small></div><span class="badge" :class="doc.status === 'READY' ? 'success' : ''">{{ statusLabel(doc.status) }}</span><button class="icon-button" aria-label="查看文档" @click="router.push('/knowledge')"><ChevronRight :size="18"/></button></div><div v-if="!docs.length" class="empty compact">上传第一份资料，开始积累团队知识。</div></div>
      <div class="workspace-footnote"><ShieldCheck :size="14"/>所有检索与引用均遵循当前账号的数据权限<span>{{ dashboard.mode === 'demo' ? '当前为原文摘录演示模式' : '已配置模型服务' }}</span></div>
    </template>

    <template v-else-if="section === 'knowledge'">
      <div class="knowledge-layout"><div class="kb-list panel"><div class="list-caption">知识库 <span>{{ kbs.length }}</span></div><button v-for="kb in kbs" :key="kb.id" :class="{ selected: selectedKb === kb.id }" @click="selectedKb = kb.id"><Library :size="17"/><span>{{ kb.name }}<small>{{ kb.visibility === 'tenant' ? '团队可见' : '私有' }}</small></span></button><div v-if="!kbs.length" class="empty compact">暂无知识库</div></div><div class="panel documents-panel"><div class="panel-toolbar"><div class="search-input"><Search :size="16"/><input v-model="filter" aria-label="筛选文档" placeholder="搜索当前列表中的文档"/></div><button class="primary" :disabled="!selectedKb || busy" @click="versionTarget = ''; fileInput?.click()"><Upload :size="16"/>上传文档</button><input ref="fileInput" class="hidden" type="file" accept=".pdf,.docx,.txt,.md" @change="uploadFile"/></div><p class="format-note">支持 PDF、DOCX、TXT、Markdown · 单文件 20 MB · PDF 最多 200 页</p><div class="table-scroll"><table><thead><tr><th>文档名称</th><th>状态</th><th>发布版本</th><th>操作</th></tr></thead><tbody><tr v-for="doc in visibleDocs" :key="doc.id"><td><div class="table-title"><FileText :size="18"/>{{ doc.title }}</div><small v-if="doc.error_code" class="error-code">{{ doc.error_code }}</small></td><td><span class="badge" :class="doc.status === 'READY' ? 'success' : doc.status === 'FAILED' ? 'danger' : ''">{{ statusLabel(doc.status) }}</span></td><td>{{ doc.active_version ? 'V' + doc.active_version : '—' }}</td><td><div class="table-actions"><button @click="download(doc)">下载</button><button @click="versionTarget = doc.id; fileInput?.click()">更新</button><button @click="protect(async () => { await api(`/documents/${doc.id}/reindex`, { method: 'POST' }); await loadDocs() })">重试</button><button class="text-danger" @click="deleteDocument(doc)">删除</button></div></td></tr></tbody></table></div><div v-if="!visibleDocs.length" class="empty"><Upload :size="28"/><h3>让知识在这里汇聚</h3><p>上传团队资料，处理完成后即可检索与问答。</p></div></div></div>
    </template>

    <template v-else-if="section === 'chat'">
      <div class="chat-layout panel"><aside class="conversation-list"><button class="secondary full" :disabled="streaming" @click="protect(newConversation)"><Plus :size="16"/>新建对话</button><button v-for="c in conversations" :key="c.id" class="conversation-item" :class="{ selected: c.id === activeConversation }" @click="openConversation(c.id)"><MessageSquare :size="15"/><span>{{ c.title }}</span></button></aside><div class="chat-main"><div class="chat-scope"><span class="status-dot"></span>{{ dashboard.mode === 'demo' ? '原文摘录演示' : '知识问答' }}<select v-model="selectedKb" :disabled="!!activeConversation"><option value="">全部可访问知识库</option><option v-for="kb in kbs" :key="kb.id" :value="kb.id">{{ kb.name }}</option></select></div><div class="messages"><div v-if="!messages.length" class="chat-welcome"><span class="welcome-icon"><BookOpen :size="30"/></span><h2>让知识，回应你的问题。</h2><p>答案来自你有权访问的资料，每一处来源都可查阅。</p><button @click="question = '退款超过30天还能申请吗？'; send()">退款超过 30 天还能申请吗？<ArrowUpRight :size="15"/></button><button @click="question = '上传文档支持哪些格式？'; send()">上传文档支持哪些格式？<ArrowUpRight :size="15"/></button></div><article v-for="(m, index) in messages" :key="m.id || index" class="message" :class="m.role"><span class="message-avatar"><BookOpen v-if="m.role === 'assistant'" :size="17"/><span v-else>我</span></span><div class="message-content"><strong>{{ m.role === 'assistant' ? 'KnowFlow' : auth.user.display_name }}</strong><p>{{ m.content || (m.status === 'streaming' ? '正在查找资料…' : '本次回答未生成内容') }}</p><div class="references"><button v-for="r in m.references" :key="r.id" @click="openSource(r)"><FileText :size="13"/>{{ r.source_id }} · {{ r.title }} · V{{ r.version }}</button></div><small v-if="m.status !== 'completed'">{{ m.status === 'streaming' ? '正在生成…' : m.status }}</small></div></article></div><form class="composer" @submit.prevent="send"><textarea v-model="question" :disabled="streaming" aria-label="输入问题" placeholder="向团队知识库提问…" rows="2" @keydown.enter.exact.prevent="send"/><div><small>Shift + Enter 换行 · 请核对原文中的适用条件</small><button v-if="streaming" type="button" class="primary" @click="stop"><Square :size="15"/>停止</button><button v-else class="primary" :disabled="!question.trim()"><Send :size="16"/>发送</button></div></form></div></div>
    </template>

    <template v-else-if="section === 'retrieval'">
      <div class="panel padded"><form class="retrieval-form" @submit.prevent="retrieve"><select v-model="selectedKb"><option value="">全部可访问知识库</option><option v-for="kb in kbs" :key="kb.id" :value="kb.id">{{ kb.name }}</option></select><input v-model="searchQuery" required placeholder="输入问题或产品关键词" aria-label="检索问题"/><button class="primary" :disabled="busy"><Search :size="16"/>检索</button></form><div class="info-note">向量召回与关键词召回通过 RRF 融合。排名分数用于排序，不代表答案置信概率。</div></div><div class="section-heading"><h2>召回片段 <span>{{ hits.length }}</span></h2></div><article v-for="(hit, i) in hits" :key="hit.chunk_id" class="panel result-card"><span class="result-rank">{{ (i + 1).toString().padStart(2, '0') }}</span><div><h3>{{ hit.title }}<span class="badge">V{{ hit.version }}</span></h3><p class="pre-wrap">{{ hit.content }}</p><small>RRF {{ hit.score.toFixed(5) }} · {{ JSON.stringify(hit.locator) }}</small></div></article><div v-if="!hits.length" class="empty"><Search :size="28"/><p>执行检索后，在这里查看证据片段。</p></div>
    </template>

    <template v-else-if="section === 'tools'">
      <div class="two-columns"><div class="panel padded"><h2 class="panel-title"><Workflow :size="18"/>受控工具执行</h2><label>选择工具<select v-model="toolName"><option>KnowledgeSearchTool</option><option>DocumentSummaryTool</option><option>DataAnalysisTool</option></select></label><label>工具参数<textarea v-model="toolArgs" class="code-input" rows="12" spellcheck="false"/></label><button class="primary" :disabled="busy" @click="executeTool">执行只读工具<ArrowRight :size="16"/></button><p class="format-note">每次请求执行一个工具，身份与权限由服务端确定。此页面不包含自主规划。</p></div><div class="panel padded"><h2 class="panel-title">执行结果</h2><pre v-if="toolResult" class="result-json">{{ JSON.stringify(toolResult, null, 2) }}</pre><div v-else class="empty"><Database :size="28"/><p>工具结果将显示在这里。</p></div></div></div>
    </template>

    <template v-else-if="section === 'evaluation'">
      <div class="panel padded evaluation-banner"><div><span class="eyebrow">RETRIEVAL EXPERIMENT</span><h2>{{ datasets[0]?.name || '暂无评估数据集' }}</h2><p>{{ datasets[0]?.case_count || 0 }} 个问题 · 开发集 · 仅评估文档召回与排名</p></div><div class="inline"><select v-model="evalMode"><option value="dense">仅向量</option><option value="hybrid">向量 + 关键词 / RRF</option></select><button class="primary" :disabled="busy || !datasets.length" @click="evaluate">运行评估<ArrowRight :size="16"/></button></div></div><div class="section-heading"><h2>实验记录</h2></div><div v-for="run in evalRuns" :key="run.id" class="panel eval-row"><div><strong>{{ run.config_snapshot.mode === 'hybrid' ? '混合检索' : '向量基线' }}</strong><small>{{ run.id.slice(0, 8) }} · {{ date(run.created_at) }}</small></div><div><span>DocRecall@5</span><strong>{{ run.metrics.doc_recall_at_5?.toFixed(3) ?? '—' }}</strong></div><div><span>MRR@5</span><strong>{{ run.metrics.mrr_at_5?.toFixed(3) ?? '—' }}</strong></div><span class="badge" :class="run.status === 'COMPLETED' ? 'success' : ''">{{ run.status }}</span></div><div class="info-note">开发集结果用于检查实现。真实语义检索、100 条分层保留集和人工回答质量复核仍需独立验收。</div>
    </template>

    <template v-else-if="section === 'monitoring'">
      <div class="panel table-scroll"><table><thead><tr><th>调用类型</th><th>模型</th><th>状态</th><th>用量来源</th><th>追踪编号</th><th>日期</th></tr></thead><tbody><tr v-for="call in calls" :key="call.id"><td>{{ call.task_type === 'embedding' ? '文档向量化' : '回答生成' }}</td><td>{{ call.model }}</td><td><span class="badge" :class="['READY', 'completed'].includes(call.status) ? 'success' : ''">{{ call.status }}</span></td><td>{{ call.usage.source === 'provider' ? '供应商报告' : '未知' }}</td><td><code>{{ call.trace_id.slice(0, 12) }}</code></td><td>{{ date(call.created_at) }}</td></tr></tbody></table><div v-if="!calls.length" class="empty"><Clock3 :size="28"/><p>文档处理与问答完成后会留下调用记录。</p></div></div>
    </template>
  </div>

  <div v-if="showCreate" class="modal-backdrop" @click.self="showCreate = false"><form class="modal" @submit.prevent="createKb"><div class="modal-heading"><h2>新建知识库</h2><button type="button" class="icon-button" aria-label="关闭" @click="showCreate = false"><X :size="20"/></button></div><p class="muted">为一类团队知识创建清晰的归属。</p><label>知识库名称<input v-model="kbName" maxlength="120" required placeholder="例如：产品服务手册"/></label><label>简介<textarea v-model="kbDescription" maxlength="2000" rows="3" placeholder="这个知识库包含什么？"/></label><label>访问范围<select v-model="visibility"><option value="private">私有 · 仅拥有者与授权成员</option><option value="tenant">团队 · 本租户成员可读</option></select></label><button class="primary full" :disabled="busy">创建知识库<ArrowRight :size="16"/></button></form></div>
  <div v-if="source" class="drawer-backdrop" @click.self="source = null"><aside class="source-drawer"><div class="modal-heading"><span class="eyebrow">SOURCE REFERENCE</span><button class="icon-button" aria-label="关闭引用" @click="source = null"><X :size="20"/></button></div><span class="welcome-icon"><FileText :size="26"/></span><h2>{{ source.title }}</h2><span class="badge">引用版本 V{{ source.version }}</span><p class="source-excerpt">{{ source.excerpt }}</p><div class="info-note">原文位置：{{ JSON.stringify(source.locator) }}</div></aside></div>
</template>
